set-variable.value:
@{
        var t = (string)context.Variables["inputText"];
        var patterns = new [] {
            @"AKIA[0-9A-Z]{16}",
            @"\b\d{3}-\d{2}-\d{4}\b",
            @"SECRET-[A-Z0-9]+",
            @"-----BEGIN (RSA |EC )?PRIVATE KEY-----"
        };
        foreach (var p in patterns) {
            if (System.Text.RegularExpressions.Regex.IsMatch(t, p)) { return p; }
        }
        return "";
    }

send-request.set-body:
@{
          var t = (string)context.Variables["inputText"];
          return new JObject(new JProperty("text", t), new JProperty("categories", new JArray("Hate","Violence","SelfHarm","Sexual"))).ToString();
      }

set-variable.value:
@{
        try {
            var resp = (IResponse)context.Variables["csResponse"];
            var j = resp.Body.As<JObject>();
            int max = 0;
            foreach (var c in (JArray)j["categoriesAnalysis"]) {
                int s = (int)c["severity"];
                if (s > max) { max = s; }
            }
            return max;
        } catch { return -1; }
    }
